sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
async function handler({
    api,
    event,
    helpers,
    imports
}) {
    console.debug(`>>>>>>>>>>>>>>>>>>>>[Debug]\n${event.elementId}\n${event.name}\nCSP=`, api.state, "\nevent=", event);
    console.debug(">>>>>Upload File:",
        "\nFile Name:", event.payload.name,
        "\nFile Size:", event.payload.size
    );
    //  debugger;

    const file = event.payload; // Fileオブジェクト;
    api.setState("uploadFileName", file.name);
    api.setState("uploadFileObject", file);


    // OOTBの通知スクリプトがあるので、そちらを利用する方法に変更
